import fs from 'node:fs';
import path from 'node:path';

const FALLBACK_PATTERNS = [
  'This section was generated by the deterministic fallback template.',
  'This document was generated by the deterministic fallback template.',
  'Fill in concrete users, constraints, evidence, and execution details before delivery.',
  'Expand it with concrete facts, edge cases, and next actions before delivery.'
];

const PLACEHOLDER_PATTERNS = [
  'before delivery',
  'fill in concrete',
  'expand it with concrete facts',
  'placeholder',
  'TBD',
  'TODO'
];

const TABLE_ENUMERATION_TITLES = new Set([
  '\u529f\u80fd\u6e05\u5355'
]);

function stripMarkdownCodeLiterals(raw) {
  return raw
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`[^`\r\n]+`/g, ' ');
}

function stripPlaceholderPolicyLines(raw) {
  return raw
    .split(/\r?\n/)
    .filter((line) => {
      const normalized = line.toLowerCase();
      const mentionsPlaceholderPattern = PLACEHOLDER_PATTERNS.some((pattern) =>
        normalized.includes(pattern.toLowerCase())
      );
      if (!mentionsPlaceholderPattern) {
        return true;
      }

      return !/\b(no|not|without|avoid|reject|block|forbid|prohibit)\b|must not|should not|不得|不能|不要|禁止|无/.test(normalized);
    })
    .join('\n');
}

function countMarkdownTableRows(raw) {
  const tableLines = raw
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => /^\|.*\|$/.test(line));
  const contentRows = tableLines.filter((line) => !/^\|(?:\s*:?-+:?\s*\|)+$/.test(line));
  return Math.max(0, contentRows.length - 1);
}

function usesTableEnumeration(rawContent, filePath) {
  const firstHeading = (rawContent.match(/^#\s+(.+)$/m) ?? [])[1]?.trim() ?? '';
  if (TABLE_ENUMERATION_TITLES.has(firstHeading)) {
    return true;
  }
  const normalizedPath = path.resolve(filePath).replace(/\\/g, '/');
  return normalizedPath.endsWith('/04-\u529f\u80fd\u6e05\u5355.md');
}

const PROFILE_MAP = {
  '# 原始需求': {
    targetLength: 760,
    minimumScore: 88,
    minimumSpecificitySignals: 3,
    minimumActionabilitySignals: 3,
    sectionContracts: [
      { heading: '## 目标用户', minBullets: 2, patterns: [/(用户|角色|团队|负责人|执行者|内容|创作|运营|使用者)/i, /(场景|任务|负责|需要|用于|使用|在.+时)/i] },
      { heading: '## 核心问题', minBullets: 2, patterns: [/(问题|痛点|困难|缺少|无法|低效|返工|遗漏|混乱|断裂)/i] },
      { heading: '## 核心价值', minBullets: 2, patterns: [/(价值|帮助|提升|减少|统一|沉淀|加速|复用|提高|降低)/i] },
      { heading: '## 显性限制', minBullets: 2, patterns: [/(限制|约束|边界|仅|必须|不能|不做|范围|兼容|本地|阶段)/i] },
      { heading: '## 待确认问题', minBullets: 2, patterns: [/(是否|待确认|未决|未知|还需|确认|？|\?)/i] }
    ],
    wholeDocumentChecks: [
      { reason: 'discover artifact is missing explicit success criteria', test: (content) => /(成功标准|验收标准|成功判定|衡量方式|完成标准|验收条件)/i.test(content) },
      { reason: 'discover artifact is missing next clarification actions', test: (content) => /(下一步|后续|接下来|澄清动作|确认动作|进入澄清|后续阶段)/i.test(content) }
    ]
  },
  '# 需求澄清': {
    targetLength: 820,
    minimumScore: 88,
    minimumSpecificitySignals: 3,
    minimumActionabilitySignals: 3,
    sectionContracts: [
      { heading: '## 使用方式', minBullets: 2, patterns: [/(步骤|操作|流程|进入|点击|切换|生成|编辑|保存|导出|工作台|页面)/i] },
      { heading: '## 输入与输出', minBullets: 2, patterns: [/(输入|输出|格式|目录|文件|文档|md|pdf|txt|表格|工件|路径|结构)/i] },
      { heading: '## 关键约束', minBullets: 2, patterns: [/(约束|必须|不能|限制|权限|兼容|安全|成本|性能|本地|模型)/i] },
      { heading: '## 风险与边界', minBullets: 2, patterns: [/(风险|边界|失败|异常|冲突|恢复|降级|不做|超出|损坏|误用)/i] },
      { heading: '## 待确认问题', minBullets: 2, patterns: [/(是否|待确认|未决|未知|还需|确认|？|\?)/i] }
    ],
    wholeDocumentChecks: [
      { reason: 'clarify artifact is missing explicit next-stage inputs', test: (content) => /(下一阶段|后续阶段|交付输入|进入方案|进入计划|基线输入|下游输入)/i.test(content) },
      { reason: 'clarify artifact is missing explicit output contract details', test: (content) => /(输出格式|目录结构|工件|文档结构|输出目录|文件格式)/i.test(content) }
    ]
  }
};

function inferProfile(content) {
  const firstHeading = (content.match(/^#\s+.+$/m) ?? [])[0]?.trim();
  return firstHeading ? PROFILE_MAP[firstHeading] ?? null : null;
}

function extractSections(content) {
  const lines = content.split(/\r?\n/);
  const sections = new Map();
  let currentHeading = '';
  for (const rawLine of lines) {
    const line = rawLine.trimEnd();
    if (/^##\s+/.test(line)) {
      currentHeading = line.trim();
      if (!sections.has(currentHeading)) {
        sections.set(currentHeading, []);
      }
      continue;
    }
    if (currentHeading) {
      sections.get(currentHeading).push(line);
    }
  }
  return sections;
}

export function reviewMarkdownArtifact(filePath, options = {}) {
  const content = fs.readFileSync(filePath, 'utf8');
  const trimmed = content.trim();
  const qualityTier = options.qualityTier ?? 'strict';
  const profile = inferProfile(content);
  const headings = content.match(/^#{1,6}\s+/gm) ?? [];
  const bullets = content.match(/^\s*[-*]\s+/gm) ?? [];
  const tableRowCount = countMarkdownTableRows(content);
  const listMarkerCount = usesTableEnumeration(content, filePath)
    ? Math.max(bullets.length, tableRowCount)
    : bullets.length;
  const codeFenceCount = (content.match(/```/g) ?? []).length;
  const placeholderScanSource = stripPlaceholderPolicyLines(stripMarkdownCodeLiterals(trimmed));
  const fallbackHits = FALLBACK_PATTERNS.filter((pattern) => placeholderScanSource.includes(pattern));
  const placeholderHits = PLACEHOLDER_PATTERNS.filter((pattern) =>
    placeholderScanSource.toLowerCase().includes(pattern.toLowerCase())
  );
  const targetLength = options.minimumLength ?? profile?.targetLength ?? (qualityTier === 'strict' ? 600 : 240);
  const specificitySignals = [
    /\d/.test(content),
    /`[^`]+`/.test(content),
    /(?:\/|\\)[A-Za-z0-9._/-]+/.test(content),
    /(?:must|shall|need|risk|constraint|output|input|repair|evidence|artifact|stage|flow|node|用户|约束|风险|输出|输入|阶段|流程|证据|工件|节点|修复|回退)/i.test(content)
  ].filter(Boolean).length;
  const actionSignals = [
    /(?:must|shall|need|should|步骤|操作|执行|检查|验证|确认|修复|恢复|导出|回滚|输入|输出|约束|规则|阶段|流程)/i.test(content),
    /\b(?:error|retry|recover|rollback|verify|check|acceptance|contract|export|approve|rerun|checkpoint)\b/i.test(content),
    /(?:\/|\\)[A-Za-z0-9._/-]+/.test(content),
    /\d/.test(content),
    /^\s*\d+\.\s+/m.test(content),
    /(?:验收|成功标准|阈值|下一步|下一阶段|输入基线|输出合同|审批记录|阻断|基线|SLA)/i.test(content),
    /(?:异常|恢复|回滚|repair|retry|重跑|checkpoint)/i.test(content),
    /(?:导出包|manifest\.json|exports\/|output\/|input\/)/i.test(content)
  ].filter(Boolean).length;

  const reasons = [];
  let score = 0;
  const lengthScore = Math.min(35, Math.round((Math.min(trimmed.length, targetLength) / Math.max(targetLength, 1)) * 35));
  const headingScore = headings.length >= 6 ? 18 : headings.length >= 4 ? 15 : headings.length >= 3 ? 12 : headings.length >= 2 ? 8 : 2;
  const bulletScore = listMarkerCount >= 6 ? 12 : listMarkerCount >= 3 ? 10 : listMarkerCount >= 1 ? 6 : 0;
  const specificityScore = Math.min(20, specificitySignals * 5);
  const codeFenceScore = codeFenceCount <= 12 ? 15 : 5;
  let hygienePenalty = 0;

  score += lengthScore;
  score += headingScore;
  score += bulletScore;
  score += specificityScore;
  score += Math.min(10, actionSignals * 3);
  score += codeFenceScore;

  if (profile) {
    const sections = extractSections(content);
    let profileBonus = 0;
    const profilePenalties = [];
    for (const contract of profile.sectionContracts) {
      const lines = sections.get(contract.heading) ?? [];
      const bulletCount = lines.filter((line) => /^\s*[-*]\s+/.test(line)).length;
      const sectionText = lines.join('\n');
      const signalMatches = contract.patterns.filter((pattern) => pattern.test(sectionText)).length;
      if (bulletCount < contract.minBullets || signalMatches < 1) {
        profilePenalties.push(`${contract.heading} lacks concrete, stage-specific detail`);
      } else {
        profileBonus += 3;
      }
    }
    for (const check of profile.wholeDocumentChecks) {
      if (!check.test(content)) {
        profilePenalties.push(check.reason);
      } else {
        profileBonus += 3;
      }
    }
    score += Math.min(18, profileBonus);
    if (profilePenalties.length) {
      reasons.push(...profilePenalties);
      score -= Math.min(30, profilePenalties.length * 6);
    }
  }

  if (trimmed.length < targetLength) reasons.push(`length ${trimmed.length} below target ${targetLength}`);
  if (headings.length < 3) reasons.push(`only ${headings.length} markdown heading markers found`);
  if (listMarkerCount < 2) reasons.push(`only ${listMarkerCount} list markers found`);
  if (specificitySignals < (profile?.minimumSpecificitySignals ?? 2)) reasons.push('content specificity signals are weak');
  if (actionSignals < (profile?.minimumActionabilitySignals ?? 2)) reasons.push('content actionability signals are weak');
  if (codeFenceCount > 12) {
    reasons.push(`too many code fences: ${codeFenceCount}`);
    score -= 10;
    hygienePenalty += 10;
  }
  if (placeholderHits.length) {
    reasons.push(`placeholder patterns detected: ${placeholderHits.join(', ')}`);
    const penalty = Math.min(35, placeholderHits.length * 14);
    score -= penalty;
    hygienePenalty += penalty;
  }
  if (fallbackHits.length) {
    reasons.push(`deterministic fallback markers detected: ${fallbackHits.join(', ')}`);
    score = Math.min(score, 18);
    hygienePenalty += 45;
  }
  if (reasons.length) {
    score = Math.min(score, 89);
  }

  score = Math.max(0, Math.min(100, Math.round(score)));
  const dimensions = {
    completeness: Math.max(0, Math.min(100, Math.round(((lengthScore + headingScore + bulletScore) / 65) * 100))),
    structure: Math.max(0, Math.min(100, Math.round(((headingScore + bulletScore + codeFenceScore) / 45) * 100))),
    specificity: Math.max(0, Math.min(100, Math.round((specificityScore / 20) * 100))),
    actionability: Math.max(0, Math.min(100, Math.round((Math.min(actionSignals, 6) / 6) * 100))),
    hygiene: Math.max(0, Math.min(100, 100 - hygienePenalty))
  };
  const deliveryReasons = [];
  let deliveryScore = Math.round(
    dimensions.completeness * 0.22
    + dimensions.structure * 0.16
    + dimensions.specificity * 0.28
    + dimensions.actionability * 0.24
    + dimensions.hygiene * 0.10
  );
  if (dimensions.completeness < 90) {
    deliveryReasons.push('delivery completeness is below the 90 bar');
  }
  if (dimensions.structure < 90) {
    deliveryReasons.push('delivery structure is below the 90 bar');
  }
  if (dimensions.specificity < 90) {
    deliveryReasons.push('delivery specificity is below the 90 bar');
  }
  if (dimensions.actionability < 90) {
    deliveryReasons.push('delivery actionability is below the 90 bar');
  }
  if (dimensions.hygiene < 95) {
    deliveryReasons.push('delivery hygiene is below the strict bar');
  }
  if (fallbackHits.length || placeholderHits.length) {
    deliveryScore = Math.min(deliveryScore, 59);
  }
  if (reasons.length) {
    deliveryScore = Math.min(deliveryScore, 89);
    deliveryReasons.push(...reasons.slice(0, 3));
  }
  deliveryScore = Math.max(0, Math.min(100, deliveryScore));
  const deliveryBand = deliveryScore >= 90
    ? 'excellent'
    : deliveryScore >= 80
      ? 'strong'
      : deliveryScore >= 72
        ? 'acceptable'
        : deliveryScore >= 60
          ? 'weak'
          : 'critical';
  const deliveryVerdict = fallbackHits.length || placeholderHits.length
    ? 'fail'
    : reasons.length === 0 && deliveryScore >= 90
      ? 'pass'
      : deliveryScore >= 80
        ? 'warn'
        : 'fail';
  const band = score >= 90
    ? 'excellent'
    : score >= 80
      ? 'strong'
      : score >= 72
        ? 'acceptable'
        : score >= 60
          ? 'weak'
          : 'critical';

  let verdict = 'pass';
  if (fallbackHits.length) {
    verdict = 'fail';
  } else if (qualityTier === 'strict' && score < (profile?.minimumScore ?? 72)) {
    verdict = 'fail';
  } else if (score < 60) {
    verdict = 'fail';
  } else if (score < 75 || placeholderHits.length || reasons.length > 0) {
    verdict = 'warn';
  }

  return {
    filePath: path.resolve(filePath),
    qualityTier,
    verdict,
    band,
    score,
    dimensions,
    deliveryScore,
    deliveryBand,
    deliveryVerdict,
    deliveryReasons,
    length: trimmed.length,
    headingCount: headings.length,
    bulletCount: bullets.length,
    tableRowCount,
    listMarkerCount,
    codeFenceCount,
    fallbackHits,
    placeholderHits,
    reasons
  };
}
